from typing import Any, Dict, List

class DocumentRequest:
    def __init__(self, document_id: str, document_type: str):
        self.document_id = document_id
        self.document_type = document_type

    def to_dict(self) -> Dict[str, Any]:
        return {
            'document_id': self.document_id,
            'document_type': self.document_type
        }

class DocumentResponse:
    def __init__(self, document_id: str, extracted_fields: Dict[str, Any]):
        self.document_id = document_id
        self.extracted_fields = extracted_fields

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'DocumentResponse':
        return cls(
            document_id=data['document_id'],
            extracted_fields=data['extracted_fields']
        )

    def to_dict(self) -> Dict[str, Any]:
        return {
            'document_id': self.document_id,
            'extracted_fields': self.extracted_fields
        }

def normalize_document_fields(extracted_fields: Dict[str, Any]) -> Dict[str, Any]:
    normalized_fields = {}
    for key, value in extracted_fields.items():
        normalized_fields[key.lower()] = value
    return normalized_fields

import boto3

def validate_document_fields(document):
    textract = boto3.client('textract')
    response = textract.analyze_document(
        Document={'Bytes': document},
        FeatureTypes=['FORMS'])
    blocks = response['Blocks']
    required_fields = ['vendor', 'date', 'total']
    field_confidence = {}
    for block in blocks:
        if block['BlockType'] == 'KEY_VALUE_SET':
            key = block['Text'].lower()
            if key in required_fields:
                field_confidence[key] = block['Confidence']
    for field in required_fields:
        if field not in field_confidence or field_confidence[field] < 70:
            return False, f"Missing or low confidence for field: {field}"
    return True, 'All required fields validated successfully'

import boto3

def extract_receipt_fields(document):
    textract_client = boto3.client('textract')
    response = textract_client.analyze_document(
        Document={'Bytes': document},
        FeatureTypes=['FORMS', 'TABLES']
    )
    merchant = None
    tax = None
    total = None
    items = []
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            if 'Merchant' in block['Text']:
                merchant = block['Text'].replace('Merchant', '').strip()
            elif 'Tax' in block['Text']:
                tax = block['Text'].replace('Tax', '').strip()
            elif 'Total' in block['Text']:
                total = block['Text'].replace('Total', '').strip()
        elif block['BlockType'] == 'TABLE':
            for relationship in block['Relationships']:
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        child_block = next(b for b in response['Blocks'] if b['Id'] == child_id)
                        if child_block['BlockType'] == 'CELL':
                            items.append(child_block['Text'].strip())
    return {
        'merchant': merchant,
        'tax': tax,
        'total': total,
        'items': items
    }

import boto3

def extract_invoice_fields(document):
    textract = boto3.client('textract')
    response = textract.analyze_document(
        Document={'Bytes': document},
        FeatureTypes=['FORMS']
    )

    vendor = None
    date = None
    total = None
    line_items = []

    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            if 'VENDOR' in block['Text']:
                vendor = block['Text'].replace('VENDOR', '').strip()
            elif 'DATE' in block['Text']:
                date = block['Text'].replace('DATE', '').strip()
            elif 'TOTAL' in block['Text']:
                total = block['Text'].replace('TOTAL', '').strip()
        elif block['BlockType'] == 'LINE':
            if 'LINE ITEM' in block['Text']:
                line_items.append(block['Text'].replace('LINE ITEM', '').strip())

    return {
        'vendor': vendor,
        'date': date,
        'total': total,
        'line_items': line_items
    }
